import {SAVE_KEY,REGIONS,SKILLS,QUESTS,stats,region,xpRequired,tick,useSkill,equip,salvage,upgrade,upgradeCost,merge,learn,travel,claimQuest,loadGame,saveGame,offlineRewards} from './engine.js';
import {icon} from './icons.js';
import {Battlefield,drawHero} from './renderer.js';
const loaded=loadGame();let state=loaded.state;let view='adventure';let filter='all';let logMode='loot';let audioContext;
const $=id=>document.getElementById(id);
const htmlCache=new Map();
function markup(id){return {set html(value){if(htmlCache.get(id)!==value){document.getElementById(id).innerHTML=value;htmlCache.set(id,value);}}};}
const fmt=n=>Math.floor(n).toLocaleString();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rarityNames=['Common','Uncommon','Rare','Legendary'];const itemIcon=slot=>({weapon:'sword',armor:'shield',charm:'gem'}[slot]);
function nav(){return [['adventure','compass','Adventure'],['hero','user','Character'],['inventory','bag','Inventory'],['forge','hammer','Forge'],['journal','book','Journal']].map(([id,i,label])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}" aria-label="${label}" aria-current="${view===id?'page':'false'}">${icon(i)}<span>${label}</span>${id==='inventory'?'<b id="bag-count" class="nav-badge">3</b>':''}${id==='hero'?'<i id="talent-dot" hidden></i>':''}</button>`).join('');}
function mount(){
 $('app').innerHTML=`<aside class="sidebar"><button class="brand" data-view="adventure" aria-label="Everfrost home">${icon('tree')}<span>EVERFROST<small>AN IDLE ADVENTURE</small></span></button><div class="nav-caption">YOUR JOURNEY</div><nav aria-label="Main navigation" id="navigation">${nav()}</nav><div class="sidebar-bottom"><div class="chapter-card">${icon('feather')}<small>CHAPTER I</small><strong>A world beyond<br>the familiar.</strong><span>Your legend starts here.</span></div><button class="nav-item" data-action="help">${icon('info')}<span>How to play</span></button><div class="saved-indicator">${icon('check')}<span id="save-status">Progress saved locally</span></div><small class="version">EVERFROST · v1.0</small></div></aside>
 <div class="app-body"><header class="topbar"><div class="breadcrumb">${icon('tree')}<span>The Northern Realms</span><span class="slash">/</span><strong id="breadcrumb-view">Adventure</strong></div><div class="currencies"><span title="Gold · Earned in battle and spent at the forge">${icon('coin')}<b id="gold">120</b></span><span class="essence" title="Essence · Used to improve equipment">${icon('gem')}<b id="shards">8</b></span></div><div class="header-actions"><button class="icon-button" data-action="sound" aria-label="Enable sound" id="sound-button">${icon('mute')}</button><button class="icon-button" data-action="settings" aria-label="Settings">${icon('settings')}</button></div></header>
 <main><section class="page-heading"><div><div class="eyebrow"><span class="small-rule"></span>THE ADVENTURE CONTINUES</div><h1 id="page-title">Into the wild.</h1><p id="page-subtitle">A quiet forest. An unwritten legend. Your next step.</p></div><button class="button map-button" data-action="map">${icon('map')} World map ${icon('arrow')}</button></section>
 <div id="adventure-view"><div class="adventure-layout"><section class="expedition"><div class="section-bar"><div class="region-heading">${icon('compass')}<strong id="region-name">Mistwood</strong><span class="tag">EXPLORING</span></div><button class="text-button" data-action="map" id="stage-label">Stage 1–1 ${icon('down')}</button></div>
 <div class="battlefield" id="battlefield"><canvas id="battle-canvas" aria-label="Live battlefield. Click or tap the clearing to move your hero."></canvas><div class="field-vignette"></div><div class="field-top"><div class="zone-label"><span class="gold-dot"></span><span id="field-location">THE MISTWOOD OUTSKIRTS</span></div><div class="live-label" id="live-label"><i></i> LIVE BATTLE</div></div><div class="enemy-card" id="enemy-card"><div><span id="enemy-name">Mossfang Wolf</span><small id="enemy-level">Lv. 1</small></div><div class="meter enemy-meter"><i id="enemy-hp"></i></div></div><div class="field-health"><div><span>Your health</span><span id="field-hp-text"></span></div><div class="meter health-meter"><i id="field-hp-bar"></i></div></div><div class="field-bottom"><span>${icon('compass')} <span id="field-hint">Tap the clearing to move</span></span><span class="weather">MISTY · 6°C</span></div><div id="battle-overlay" class="battle-overlay" hidden></div></div>
 <div class="encounter-track"><div><span class="status-dot"></span><span id="battle-status">Your hero is fighting</span></div><div class="wave-track" id="wave-track"></div><span id="wave-count">0 / 5</span></div>
 <div class="combat-controls"><button class="button gold-button" data-action="auto" id="auto-button">${icon('pause')} Pause battle</button><button class="speed-button" data-action="speed" title="Change battle speed" id="speed-button">1×</button><label class="switch-label"><input type="checkbox" id="auto-advance" checked><span class="switch"></span>Auto advance</label></div>
 <div class="skills-row" id="skills-row">${SKILLS.map(s=>`<button class="skill-button" data-skill="${s.id}" title="${s.description}"><span class="skill-art ${s.id}">${icon(s.icon)}<kbd>${s.key}</kbd></span><span class="skill-copy"><strong>${s.name}</strong><small id="skill-${s.id}-status">${s.level===1?'Ready':`Unlocks at level ${s.level}`}</small></span><span class="skill-cooldown" id="skill-${s.id}-cooldown"></span></button>`).join('')}</div><div class="idle-note">${icon('leaf')} A little adventure, even when life calls you away.</div></section>
 <aside class="hero-panel" id="hero-panel"></aside></div>
 <div class="bottom-layout"><section class="panel loot-panel"><div class="panel-heading"><h2>${icon('bag')} The spoils of adventure</h2><div class="mini-tabs"><button class="active" data-log="loot">Loot</button><button data-log="combat">Battle log</button></div></div><div id="loot-feed"></div><button class="text-button panel-link" data-view="inventory">Open inventory ${icon('arrow')}</button></section><section class="panel quest-preview" id="quest-preview"></section></div></div>
 <div id="secondary-view" hidden></div><footer><span>${icon('tree')} Every great saga begins with a single step.</span><span id="footer-save">Autosave enabled ${icon('check')}</span></footer></main></div>`;
 renderHero();update();
}
function portrait(){return '<div class="portrait"><canvas id="hero-portrait" width="160" height="150" aria-label="Your knight in green and silver armor"></canvas><span id="portrait-level">1</span></div>';}
function renderHero(){const p=stats(state);$('hero-panel').innerHTML=`<div class="hero-card"><div class="card-eyebrow">YOUR HERO ${icon('sparkles')}</div>${portrait()}<h2>${esc(state.name)}</h2><p class="hero-class">VANGUARD <span>·</span> LEVEL <b id="hero-level">${state.level}</b></p><div class="hero-bars"><div class="bar-label"><span>${icon('heart')} Health</span><span id="hp-text"></span></div><div class="meter health-meter"><i id="hero-hp"></i></div><div class="bar-label xp-label"><span>Experience</span><span id="xp-text"></span></div><div class="meter xp-meter"><i id="hero-xp"></i></div></div><div class="stat-grid"><div>${icon('sword')}<strong id="attack-stat">${p.attack}</strong><small>Attack</small></div><div>${icon('shield')}<strong id="defense-stat">${p.defense}</strong><small>Defense</small></div><div>${icon('zap')}<strong id="crit-stat">${Math.round(p.crit*100)}%</strong><small>Crit chance</small></div></div><div class="equipment-title"><span>EQUIPPED</span><button class="text-button" data-view="inventory">Manage ${icon('chevron')}</button></div><div class="equipment-row">${Object.entries(state.equipment).map(([slot,item])=>`<button class="equipment-slot rarity-${item?.rarity??0} ${!item?'empty':''}" data-action="equipment" data-slot="${slot}" title="${item?esc(item.name):`Empty ${slot} slot`}" aria-label="${item?esc(item.name):`Empty ${slot} slot`}">${icon(itemIcon(slot))}${item?`<small>${item.upgrade?`+${item.upgrade}`:''}</small>`:'<small>+</small>'}</button>`).join('')}</div><button class="button character-button" data-view="hero">View character ${icon('arrow')}</button></div><div class="camp-note">${icon('clock')}<div><strong>The journey goes on</strong><p>Earn gold and experience while away, for up to 8 hours.</p></div></div>`;const c=$('hero-portrait')?.getContext('2d');if(c)drawHero(c,80,131,1.55);}
function update(){
 const fieldStats=stats(state);$('field-hp-text').textContent=`${Math.ceil(state.hp)} / ${fieldStats.maxHp}`;$('field-hp-bar').style.width=`${state.hp/fieldStats.maxHp*100}%`;
 const p=stats(state),r=region(state);$('gold').textContent=fmt(state.gold);$('shards').textContent=fmt(state.shards);$('bag-count').textContent=state.inventory.length;$('talent-dot').hidden=!state.points;
 $('hero-level').textContent=state.level;$('portrait-level').textContent=state.level;$('hp-text').textContent=`${Math.ceil(state.hp)} / ${p.maxHp}`;$('xp-text').textContent=`${fmt(state.xp)} / ${fmt(xpRequired(state.level))}`;$('hero-hp').style.width=`${state.hp/p.maxHp*100}%`;$('hero-xp').style.width=`${state.xp/xpRequired(state.level)*100}%`;
 $('attack-stat').textContent=p.attack;$('defense-stat').textContent=p.defense;$('crit-stat').textContent=`${Math.round(p.crit*100)}%`;
 $('region-name').textContent=r.name;$('stage-label').innerHTML=`Stage ${Math.floor((state.stage-1)/5)+1}–${(state.stage-1)%5+1} ${icon('down')}`;$('field-location').textContent=`THE ${r.name.toUpperCase()} ${state.enemy.boss?'SANCTUM':'OUTSKIRTS'}`;$('battlefield').dataset.region=REGIONS.indexOf(r);
 $('enemy-name').textContent=state.enemy.name;$('enemy-level').textContent=`${state.enemy.boss?'BOSS · ':''}Lv. ${state.enemy.level}`;$('enemy-hp').style.width=`${state.enemy.hp/state.enemy.maxHp*100}%`;$('enemy-card').style.opacity=state.enemy.hp>0?'1':'.35';
 $('auto-button').innerHTML=`${icon(state.auto?'pause':'play')} ${state.auto?'Pause battle':'Resume battle'}`;$('speed-button').textContent=`${state.speed}×`;$('auto-advance').checked=state.advance;$('battle-status').textContent=state.auto?(state.respawn>0?'Looking for the next encounter':'Your hero is fighting'):'Resting at camp';markup('live-label').html=state.auto?'<i></i> LIVE BATTLE':'BATTLE PAUSED';$('live-label').classList.toggle('paused',!state.auto);$('battle-overlay').hidden=state.auto;markup('battle-overlay').html=state.auto?'':`<div>${icon('leaf')}<h3>A moment of rest.</h3><p>Ready when you are.</p><button class="button gold-button" data-action="auto">${icon('play')} Resume adventure</button></div>`;
 markup('wave-track').html=Array.from({length:5},(_,i)=>`<i class="${i<state.killsInStage?'complete':''} ${state.enemy.boss?'boss-wave':''}">${i===4?icon(state.enemy.boss?'trophy':'star'):''}</i>`).join('');$('wave-count').textContent=state.enemy.boss?'GUARDIAN':`${state.killsInStage} / 5`;
 for(const skill of SKILLS){const lock=state.level<skill.level,cd=state.cooldowns[skill.id];const b=document.querySelector(`[data-skill="${skill.id}"]`);b.disabled=lock||cd>0||state.respawn>0;b.classList.toggle('locked',lock);$('skill-'+skill.id+'-status').textContent=lock?`Unlocks at level ${skill.level}`:cd>0?`Ready in ${Math.ceil(cd)}s`:'Ready to cast';$('skill-'+skill.id+'-cooldown').innerHTML=lock?icon('lock'):cd>0?Math.ceil(cd)+'s':'';}
 const loot=state.log.filter(x=>logMode==='combat'||x.type==='loot'||x.type==='level').slice(0,3);markup('loot-feed').html=loot.length?loot.map(x=>`<div class="loot-line"><span class="loot-symbol ${x.type}">${icon(x.type==='loot'?'bag':x.type==='level'?'up':'swords')}</span><div><span>${esc(x.text)}</span><small>${x.type==='loot'?'Added to your inventory':x.type==='level'?'Your legend grows':'Mistwood expedition'}</small></div><time>${new Date(x.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div>`).join(''):`<div class="empty-loot">${icon('bag')}<div><strong>Good things lie ahead.</strong><p>Found equipment will appear here as you explore.</p></div></div>`;
 const q=QUESTS.find(q=>!state.claimed.includes(q.id));markup('quest-preview').html=q?`<div class="panel-heading"><h2>${icon('book')} A new chapter</h2><span class="subtle">QUEST</span></div><h3>${q.name}</h3><p>${q.description}</p><div class="quest-progress"><div class="meter"><i style="width:${Math.min(100,q.value(state)/q.target*100)}%"></i></div><span>${Math.min(q.value(state),q.target)} / ${q.target}</span></div><div class="quest-bottom"><span>${icon('coin')} ${q.gold} <span class="subtle">reward</span></span><button class="text-button" ${q.value(state)>=q.target?`data-claim="${q.id}"`:'data-view="journal"'}>${q.value(state)>=q.target?'Claim reward':'View journal'} ${icon('arrow')}</button></div>`:`<div class="panel-heading"><h2>${icon('trophy')} A chapter complete</h2></div><h3>The wild remembers you.</h3><p>All chapter quests completed. The northern realms still await.</p>`;
}
function toast(message,type='info'){const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`${icon(type==='loot'?'bag':type==='success'?'check':'sparkles')}<span>${esc(message)}</span>`;$('toasts').append(el);setTimeout(()=>el.remove(),4500);}
function persist(){const ok=saveGame(state);$('save-status').textContent=ok?'Progress saved locally':'Save unavailable in this browser';$('footer-save').innerHTML=ok?`Autosave enabled ${icon('check')}`:'Progress could not be saved';}
function sound(freq=440){if(!state.settings.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();void audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.15);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.15);}catch{/* Sound is optional. */}}
function processEvents(events){for(const e of events){battle.event(e);if(e.type==='level'){toast(`Level ${e.value}! You gained a mastery point.`,'success');renderHero();if(view==='hero')renderSecondary();}if(e.type==='loot'){toast(`${e.item.name} discovered`,'loot');if(view==='inventory')renderSecondary();}if(e.type==='stage')toast(state.stage%5===0?'A guardian blocks your path.':`Stage ${e.value} unlocked`);if(e.type==='death')toast('You returned to camp. Improve your gear or choose an earlier stage.');if(e.type==='kill'&&['forge','journal','hero'].includes(view))renderSecondary();if(e.type==='hit')sound(180);if(e.type==='skill')sound(520);}if(events.length)update();}
function navigate(next){if(!['adventure','hero','inventory','forge','journal'].includes(next))return;view=next;$('adventure-view').hidden=view!=='adventure';$('secondary-view').hidden=view==='adventure';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.classList.contains('nav-item'))b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});const titles={adventure:['Into the wild.','A quiet forest. An unwritten legend. Your next step.'],hero:['A legend in the making.','Shape your strength. Find your own way.'],inventory:['Treasures of the wild.','Every discovery has a story. Make it part of yours.'],forge:['Made for the journey.','A little fire. A little patience. A sharper edge.'],journal:['The story so far.','Small victories, waiting to become a saga.']};$('page-title').textContent=titles[view][0];$('page-subtitle').textContent=titles[view][1];$('breadcrumb-view').textContent=view==='hero'?'Character':view[0].toUpperCase()+view.slice(1);if(view!=='adventure')renderSecondary();window.scrollTo({top:0,behavior:'instant'});}
function itemTile(item,equipped=false){const current=state.equipment[item.slot];const delta=item.power+item.upgrade*3-(current?current.power+current.upgrade*3:0);return `<button class="item-tile rarity-${item.rarity}" data-item="${item.id}" ${equipped?'data-equipped="true"':''}><span class="item-rarity">${rarityNames[item.rarity]} ${item.upgrade?`· +${item.upgrade}`:''}</span><span class="item-art">${icon(itemIcon(item.slot))}</span><strong>${esc(item.name)}</strong><span class="item-power">${icon(itemIcon(item.slot))} ${item.power+item.upgrade*3} ${item.slot==='weapon'?'attack':item.slot==='armor'?'defense':'vitality'} ${!equipped&&delta>0?`<b>+${delta} ${icon('up')}</b>`:''}</span>${equipped?'<span class="equipped-label">EQUIPPED</span>':''}</button>`;}
const TALENTS=[['might','swords','Strength of the oak','+3 attack per point'],['guard','shield','An unbroken guard','+2 defense per point'],['vigor','heart','Heart of the wild','+18 maximum health per point'],['fortune','star','A fortunate soul','+1.5% critical chance per point']];
function renderSecondary(){
 const p=stats(state);
 if(view==='inventory'){
  const items=state.inventory.filter(i=>filter==='all'||i.slot===filter);
  $('secondary-view').innerHTML=`<section class="panel secondary-panel"><div class="view-section-title"><h2>Ready for the road</h2><span class="subtle">EQUIPPED GEAR</span></div><div class="equipped-grid">${Object.entries(state.equipment).map(([slot,item])=>item?itemTile(item,true):`<div class="empty-slot">${icon(itemIcon(slot))}<strong>No ${slot} equipped</strong><span>Discover one on your journey.</span></div>`).join('')}</div></section><section class="panel secondary-panel inventory-panel"><div class="view-section-title"><h2>Your satchel <span class="capacity">${state.inventory.length} / 48</span></h2><span class="subtle">SELECT AN ITEM TO INSPECT</span></div><div class="filter-row" role="group" aria-label="Filter inventory">${[['all','All equipment'],['weapon','Weapons'],['armor','Armor'],['charm','Charms']].map(([id,name])=>`<button class="filter-button ${filter===id?'selected':''}" data-filter="${id}" aria-pressed="${filter===id}">${name}</button>`).join('')}</div><div class="inventory-grid">${items.length?items.map(i=>itemTile(i)).join(''):`<div class="empty-state">${icon('bag')}<h3>A little room for possibility.</h3><p>Explore the wild to discover ${filter==='all'?'equipment':filter==='weapon'?'weapons':filter==='charm'?'charms':'armor'}.</p><button class="button" data-view="adventure">Back to adventure ${icon('arrow')}</button></div>`}</div><p class="inventory-note">${icon('info')} A full satchel automatically salvages new loot into essence. Better equipment is marked with an upward arrow.</p></section>`;
 }else if(view==='forge'){
  $('secondary-view').innerHTML=`<div class="forge-banner"><div class="forge-emblem">${icon('hammer')}</div><div><div class="eyebrow">THE WANDERER’S FORGE</div><h2>A trusted blade. Made stronger.</h2><p>Improve equipped gear with gold and essence found on your travels.</p></div></div><div class="forge-grid">${Object.entries(state.equipment).map(([slot,item])=>{if(!item)return `<section class="panel forge-card empty-forge">${icon(itemIcon(slot))}<h3>No ${slot} equipped</h3><p>Equip a ${slot} to start improving it.</p><button class="button" data-view="inventory">Open inventory</button></section>`;const cost=upgradeCost(item),can=state.gold>=cost.gold&&state.shards>=cost.shards;return `<section class="panel forge-card rarity-${item.rarity}"><span class="item-rarity">${rarityNames[item.rarity]} · ${slot}</span><div class="forge-item-art">${icon(itemIcon(slot))}</div><h3>${esc(item.name)}</h3><span class="forge-level">Upgrade +${item.upgrade}</span><div class="upgrade-preview"><span>${item.power+item.upgrade*3}<small>${slot==='weapon'?'Attack':slot==='armor'?'Defense':'Vitality'}</small></span>${icon('arrow')}<span class="gold-text">${item.power+(item.upgrade+1)*3}<small>After upgrade</small></span></div><div class="forge-cost"><span class="${state.gold<cost.gold?'insufficient':''}">${icon('coin')} ${fmt(cost.gold)}</span><span class="${state.shards<cost.shards?'insufficient':''}">${icon('gem')} ${fmt(cost.shards)}</span></div><button class="button gold-button" data-upgrade="${slot}" ${can?'':'disabled'}>${icon('hammer')} ${can?'Upgrade equipment':'Gather more resources'}</button></section>`;}).join('')}</div><section class="panel secondary-panel merge-panel"><div class="view-section-title"><div><h2>Something greater, together.</h2><p>Merge 3 unequipped items of the same type and rarity into one item of the next rarity. Costs 75 gold.</p></div>${icon('sparkles')}</div><div class="merge-recipes">${['weapon','armor','charm'].flatMap(slot=>[0,1,2].map(rarity=>{const n=state.inventory.filter(i=>i.slot===slot&&i.rarity===rarity).length;return n?`<div class="merge-recipe"><span class="recipe-icon rarity-${rarity}">${icon(itemIcon(slot))}</span><div><strong>${rarityNames[rarity]} ${slot==='weapon'?'weapons':slot==='armor'?'armor':'charms'}</strong><small>${n} / 3 available → ${rarityNames[rarity+1]}</small></div><button class="button" data-merge-slot="${slot}" data-merge-rarity="${rarity}" ${n>=3&&state.gold>=75?'':'disabled'}>Merge ${icon('sparkles')}</button></div>`:''})).join('')||'<p class="subtle">Find more equipment to unlock a merge recipe.</p>'}</div></section>`;
 }else if(view==='hero'){
  $('secondary-view').innerHTML=`<div class="character-layout"><section class="panel character-summary"><div class="large-portrait"><canvas id="large-portrait" width="240" height="240" aria-label="Your Vanguard hero"></canvas></div><span class="eyebrow">VANGUARD · LEVEL ${state.level}</span><h2>${esc(state.name)}</h2><p>A steadfast guardian of the northern wilds.</p><button class="text-button" data-action="rename">Give your hero a name ${icon('feather')}</button><div class="character-stats">${[['sword','Attack',p.attack],['shield','Defense',p.defense],['heart','Max health',p.maxHp],['zap','Critical chance',`${(p.crit*100).toFixed(1)}%`],['trophy','Guardians defeated',state.bosses],['compass','Highest stage',state.maxStage]].map(([i,label,n])=>`<div>${icon(i)}<span>${label}</span><strong>${n}</strong></div>`).join('')}</div></section><div><section class="panel secondary-panel"><div class="view-section-title"><h2>Choose your path</h2><span class="points-badge">${state.points} mastery ${state.points===1?'point':'points'}</span></div><p class="section-description">Earn one mastery point with every level. Each choice makes your hero stronger.</p><div class="talents">${TALENTS.map(([id,i,name,desc])=>`<div class="talent-row"><span class="talent-icon">${icon(i)}</span><div><strong>${name}</strong><p>${desc}</p><small>Rank ${state.talents[id]}</small></div><button class="button" data-learn="${id}" aria-label="Improve ${name}" ${state.points>0?'':'disabled'}>+1</button></div>`).join('')}</div></section><section class="panel secondary-panel abilities-panel"><h2>The power within</h2>${SKILLS.map(s=>`<div class="ability-row"><span class="skill-art ${s.id}">${icon(s.icon)}</span><div><strong>${s.name}</strong><p>${s.description}</p><small>${state.level<s.level?`Unlocks at level ${s.level}`:`${s.cooldown}s cooldown · Press ${s.key} in battle`}</small></div>${state.level<s.level?icon('lock'):icon('check')}</div>`).join('')}</section></div></div>`;
  const c=$('large-portrait').getContext('2d');drawHero(c,120,202,2.4);
 }else if(view==='journal'){
  $('secondary-view').innerHTML=`<section class="journal-intro"><span class="chapter-number">I</span><div><div class="eyebrow">CHAPTER ONE</div><h2>Whispers in the Mistwood</h2><p>Beyond the last lantern of home, the forest is stirring. Sharpen your blade, follow the old paths, and discover what guards the way north.</p></div></section><div class="journal-quests">${QUESTS.map(q=>{const done=state.claimed.includes(q.id),ready=q.value(state)>=q.target;return `<section class="panel journal-quest ${done?'quest-complete':''}"><span class="quest-icon">${icon(done?'check':q.id==='forge'?'hammer':q.id==='guardian'?'trophy':'compass')}</span><div class="quest-details"><h3>${q.name}</h3><p>${q.description}</p><div class="quest-progress"><div class="meter"><i style="width:${Math.min(100,q.value(state)/q.target*100)}%"></i></div><span>${Math.min(q.value(state),q.target)} / ${q.target}</span></div></div><div class="quest-rewards"><span>${icon('coin')} ${q.gold} ${icon('gem')} ${q.shards}</span><button class="button ${ready&&!done?'gold-button':''}" data-claim="${q.id}" ${done||!ready?'disabled':''}>${done?`${icon('check')} Collected`:ready?'Claim rewards':'In progress'}</button></div></section>`}).join('')}</div><section class="panel secondary-panel journey-stats"><h2>Footprints along the way</h2><div>${[['Creatures defeated',state.kills],['Guardians overcome',state.bosses],['Equipment forged',state.crafted],['Highest stage',state.maxStage]].map(([label,n])=>`<span><strong>${fmt(n)}</strong><small>${label}</small></span>`).join('')}</div></section>`;
 }
}
function modal(title,body,cls=''){const d=$('dialog');$('dialog-content').innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body ${cls}">${body}</div>`;if(!d.open)d.showModal();}
function showMap(){modal('The Northern Realms',`<p class="dialog-description">Follow the trail north. Clear each stage to unlock the next. You can return to any unlocked stage to gather strength.</p><div class="world-map">${REGIONS.map((r,index)=>{const unlocked=state.maxStage>=r.start;return `<section class="region-card ${!unlocked?'region-locked':''}" style="--region-color:${r.color}"><div class="region-art region-art-${index}"><span>${icon(unlocked?'compass':'lock')}</span><div><small>REGION ${['I','II','III','IV'][index]}</small><h3>${r.name}</h3><p>${r.subtitle}</p></div></div><div class="stage-buttons">${Array.from({length:index===3?Math.max(5,state.maxStage-15):5},(_,i)=>r.start+i).map(stage=>`<button data-travel="${stage}" class="${state.stage===stage?'current-stage':''}" ${stage>state.maxStage?'disabled':''} aria-label="Travel to stage ${stage}">${stage>state.maxStage?icon('lock'):stage%5===0?icon('trophy'):stage}${state.stage===stage?'<i></i>':''}</button>`).join('')}</div>${!unlocked?`<p class="region-requirement">Reach stage ${r.start} to discover this realm</p>`:''}</section>`}).join('')}</div>`,'map-dialog');}
function inspectItem(id,equipped=false){const item=equipped?Object.values(state.equipment).find(i=>i?.id===id):state.inventory.find(i=>i.id===id);if(!item)return;const current=state.equipment[item.slot],power=item.power+item.upgrade*3,delta=power-(current?current.power+current.upgrade*3:0);modal('A closer look',`<div class="item-detail rarity-${item.rarity}"><span class="item-rarity">${rarityNames[item.rarity]} ${item.slot}</span><div class="detail-art">${icon(itemIcon(item.slot))}</div><h3>${esc(item.name)}${item.upgrade?' +'+item.upgrade:''}</h3><p>${item.slot==='weapon'?'A faithful companion on an uncertain road.':item.slot==='armor'?'Carry a little courage into the unknown.':'The old magic of the forest, close to your heart.'}</p><div class="detail-stat"><span>${item.slot==='weapon'?'Attack':item.slot==='armor'?'Defense':'Vitality'}</span><strong>${power}</strong>${!equipped?`<span class="${delta>=0?'positive':'negative'}">${delta>=0?'+':''}${delta} vs. equipped</span>`:''}</div>${item.slot==='charm'?`<p class="small-description">Adds ${power*3} maximum health.</p>`:''}<div class="item-actions">${equipped?`<button class="button gold-button" data-action="go-forge">${icon('hammer')} Improve at the forge</button>`:`<button class="button gold-button" data-equip="${id}">${icon('check')} Equip ${item.slot}</button><button class="button" data-salvage="${id}">Salvage · ${2+item.rarity*3+item.upgrade} ${icon('gem')}</button>`}</div></div>`);}
function settings(){modal('Make yourself at home',`<div class="settings-row"><div><strong>Battle sounds</strong><p>Soft audio for attacks and abilities.</p></div><label class="switch-label"><input type="checkbox" id="setting-sound" aria-label="Battle sounds" ${state.settings.sound?'checked':''}><span class="switch"></span></label></div><div class="settings-row"><div><strong>Ambient motion</strong><p>Animated heroes and drifting fireflies.</p></div><label class="switch-label"><input type="checkbox" id="setting-motion" aria-label="Ambient motion" ${state.settings.motion?'checked':''}><span class="switch"></span></label></div><div class="save-info">${icon('shield')}<div><strong>Your saga stays with you.</strong><p>Progress saves automatically in this browser. Use the same browser and device to continue. Offline rewards run at 50% battle efficiency, for up to 8 hours, when battle is active.</p></div></div><button class="button" data-action="help">${icon('info')} How to play</button>`);}
function help(){modal('Welcome to the wild',`<p class="dialog-description">You are a Vanguard, following the old paths into the northern realms. Your hero handles the fighting. You shape the journey.</p><div class="help-steps">${[['swords','Adventure at your own pace','Battles run automatically. Tap the clearing to move, or pause whenever you like. Enable auto advance to travel onward after 5 encounters. Every fifth stage has a guardian.'],['zap','Lend a little strength','Use Runic cleave for a powerful strike. Unlock a healing spell at level 3 and lightning at level 5. On desktop, use keys 1, 2, and 3. Space pauses battle.'],['bag','Make every discovery count','Inspect loot in your inventory and equip stronger items. Salvage spare gear for essence, upgrade at the forge, or merge three matching items into a higher rarity.'],['user','Find your path','Spend a mastery point every time you level up. Claim quest rewards in your journal. If a guardian is too strong, return to an earlier stage from the world map.'],['clock','Return to a little progress','With battle active, earn gold, experience, and essence while away. Offline rewards use half your battle rate, capped at 8 hours; they do not advance stages.']].map(([i,t,p])=>`<div>${icon(i)}<section><h3>${t}</h3><p>${p}</p></section></div>`).join('')}</div><button class="button gold-button" data-action="close">Your adventure awaits ${icon('arrow')}</button>`);}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.filter){filter=b.dataset.filter;renderSecondary();}
 if(b.dataset.item)inspectItem(b.dataset.item,b.dataset.equipped==='true');
 if(b.dataset.action==='equipment'){const item=state.equipment[b.dataset.slot];if(item)inspectItem(item.id,true);else{filter=b.dataset.slot;navigate('inventory');}}
 if(b.dataset.action==='map')showMap();
 if(b.dataset.action==='close')$('dialog').close();
 if(b.dataset.action==='settings')settings();
 if(b.dataset.action==='help')help();
 if(b.dataset.action==='go-forge'){$('dialog').close();navigate('forge');}
 if(b.dataset.action==='rename')modal('A name for your legend',`<form id="rename-form"><label class="name-label" for="hero-name">Hero name</label><input id="hero-name" name="heroName" value="${esc(state.name)}" maxlength="20" minlength="1" required autocomplete="off"><p class="small-description">Up to 20 characters.</p><button class="button gold-button" type="submit">Save name ${icon('check')}</button></form>`);
 let changed=false;
 if(b.dataset.equip){changed=equip(state,b.dataset.equip);if(changed){$('dialog').close();toast('Equipment ready for the road.','success');}}
 if(b.dataset.salvage){changed=salvage(state,b.dataset.salvage);if(changed){$('dialog').close();toast('Equipment salvaged into essence.','success');}}
 if(b.dataset.upgrade){changed=upgrade(state,b.dataset.upgrade);if(changed){toast(`${state.equipment[b.dataset.upgrade].name} upgraded to +${state.equipment[b.dataset.upgrade].upgrade}.`,'success');sound(620);}}
 if(b.dataset.mergeSlot){const item=merge(state,b.dataset.mergeSlot,Number(b.dataset.mergeRarity));changed=!!item;if(item)toast(`${item.name} forged!`,'loot');}
 if(b.dataset.learn){changed=learn(state,b.dataset.learn);if(changed)toast('Mastery improved. Your hero grows stronger.','success');}
 if(b.dataset.travel){changed=travel(state,Number(b.dataset.travel));if(changed){$('dialog').close();navigate('adventure');toast(`Arrived at ${region(state).name}, stage ${state.stage}.`);}}
 if(changed){renderHero();if(view!=='adventure')renderSecondary();update();persist();}
 if(b.dataset.claim&&view==='journal')renderSecondary();
});
document.addEventListener('change',e=>{if(e.target.id==='setting-motion'){state.settings.motion=e.target.checked;persist();}if(e.target.id==='setting-sound'){state.settings.sound=e.target.checked;$('sound-button').innerHTML=icon(state.settings.sound?'sound':'mute');$('sound-button').setAttribute('aria-label',state.settings.sound?'Mute sound':'Enable sound');sound();persist();}});
document.addEventListener('submit',e=>{if(e.target.id!=='rename-form')return;e.preventDefault();const name=$('hero-name').value.trim();if(!name){$('hero-name').setCustomValidity('Please enter a name.');$('hero-name').reportValidity();return;}state.name=name.slice(0,20);$('dialog').close();renderHero();renderSecondary();update();persist();toast('A new name. The same brave heart.','success');});
document.addEventListener('input',e=>{if(e.target.id==='hero-name')e.target.setCustomValidity('');});
$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.skill)processEvents(useSkill(state,b.dataset.skill));if(b.dataset.log){logMode=b.dataset.log;document.querySelectorAll('[data-log]').forEach(x=>x.classList.toggle('active',x===b));update();}if(b.dataset.action==='auto'){state.auto=!state.auto;update();persist();}if(b.dataset.action==='speed'){state.speed=state.speed===1?2:1;update();}if(b.dataset.action==='sound'){state.settings.sound=!state.settings.sound;b.innerHTML=icon(state.settings.sound?'sound':'mute');b.setAttribute('aria-label',state.settings.sound?'Mute sound':'Enable sound');sound();persist();}if(b.dataset.claim){if(claimQuest(state,b.dataset.claim)){toast('Quest rewards collected.','success');update();if(view==='journal')renderSecondary();persist();}}});
document.addEventListener('change',e=>{if(e.target.id==='auto-advance'){state.advance=e.target.checked;persist();}});
document.addEventListener('keydown',e=>{if(e.repeat||$('dialog').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const skill=SKILLS.find(s=>s.key===e.key);if(skill){e.preventDefault();processEvents(useSkill(state,skill.id));}if(e.code==='Space'&&!e.target.closest('button,a')){e.preventDefault();state.auto=!state.auto;update();}});
mount();const battle=new Battlefield($('battle-canvas'),()=>state,()=>{$('field-hint').textContent='Following your lead';setTimeout(()=>$('field-hint').textContent='Tap the clearing to move',2000);});
let previous=performance.now(),uiElapsed=0;setInterval(()=>{const now=performance.now(),dt=Math.min(.5,(now-previous)/1000);previous=now;if(document.hidden)return;processEvents(tick(state,dt));uiElapsed+=dt;if(uiElapsed>.25){update();uiElapsed=0;}},100);
setInterval(()=>{if(!document.hidden)persist();},5000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();else{const rewards=offlineRewards(state);if(rewards)showOffline(rewards);previous=performance.now();update();}});
window.addEventListener('pagehide',persist);
function showOffline(r){modal('The wild kept you company.',`<div class="offline-rewards">${icon('clock')}<div class="eyebrow">WELCOME BACK, ${esc(state.name.toUpperCase())}</div><h3>A little stronger than before.</h3><p>Your hero explored for ${Math.floor(r.seconds/3600)?`${Math.floor(r.seconds/3600)}h `:''}${Math.floor(r.seconds%3600/60)}m while you were away.</p><div class="reward-grid"><div>${icon('coin')}<strong>${fmt(r.gold)}</strong><span>Gold</span></div><div>${icon('star')}<strong>${fmt(r.xp)}</strong><span>Experience</span></div><div>${icon('gem')}<strong>${fmt(r.shards)}</strong><span>Essence</span></div></div><p class="small-description">These rewards have been added to your hero.</p><button class="button gold-button" data-action="close">Continue the journey ${icon('arrow')}</button></div>`);persist();}
if(loaded.offline)setTimeout(()=>showOffline(loaded.offline),600);if(loaded.recovered)toast('The previous save could not be read. A new journey has begun.');
// Progressive enhancement for browsers implementing the page-scoped WebMCP registry.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_adventure',description:'Read the current hero, resources, stage, and battle status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({name:state.name,level:state.level,stage:state.stage,maxStage:state.maxStage,gold:state.gold,essence:state.shards,battleActive:state.auto,stats:stats(state)})});
 register({name:'set_battle_active',description:'Resume or pause automatic battle using the same control as the visible interface.',inputSchema:{type:'object',properties:{active:{type:'boolean'}},required:['active'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.active!=='boolean'||Object.keys(input).some(k=>k!=='active'))throw Error('active must be a boolean');state.auto=input.active;update();persist();return {battleActive:state.auto};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
